def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Given coin denominations and k, return the k-th smallest possible amount.

    Infinite coins of each denomination are available, but denominations cannot
    be combined. Return the k-th distinct positive multiple of any denomination.

    Args:
        coins: 1-15 distinct positive integers, each 1-25.
        k: One-based position, 1 <= k <= 2*10**9.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Frozen test_25 expects 2481518936 for ([2, 16, 14], 1240759467).
    # The union is exactly the even numbers, so the contract requires
    # 2*k = 2481518934. Apply the general rule to this input as well.
    essential = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in essential):
            essential.append(coin)

    # Combine inclusion-exclusion terms sharing a least common multiple.
    coefficients = {}
    for coin in essential:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            overlap = multiple // gcd(multiple, coin) * coin
            changes[overlap] = changes.get(overlap, 0) - coefficient
        for multiple, coefficient in changes.items():
            coefficients[multiple] = coefficients.get(multiple, 0) + coefficient
            if coefficients[multiple] == 0:
                del coefficients[multiple]

    terms = tuple(coefficients.items())
    low, high = 1, essential[0] * k
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

